(()=>{let i=1920,d=1080,s=document.getElementById("slideScaler");function e(){var e=window.innerWidth,t=window.innerHeight,n=Math.min(e/i,t/d),e=(e-i*n)/2,t=(t-d*n)/2;s.style.transform=`translate(${e}px, ${t}px) scale(${n})`,s.style.width=i+"px",s.style.height=d+"px"}s&&(e(),window.addEventListener("resize",e),document.addEventListener("fullscreenchange",()=>{setTimeout(e,100)}))})();